BEGIN; SET LOCAL statement_timeout='15s';
WITH secret AS MATERIALIZED(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='service_role_key'),
j AS(SELECT id FROM zoi.geography_repair_jobs WHERE id='20fccee5-acb6-4b2e-8861-14cbb1da1153'::uuid AND listing_id='02e262c3-087f-40ae-aa3c-7c5d93371fef'::uuid AND completed_lease_id='31b366db-886c-4ebb-b549-b49d23b14ba0'::uuid AND capture_result_hash='38d75bdacdb551bf2a11bad1d2f5bcfc' AND encode(extensions.digest(convert_to(source::text,'UTF8'),'sha256'),'hex')='8e7991ac869d7ac0fd00c7f24f0142e9a974d2e417dfd6f5cbb65ef50748ea7d' AND source->>'private_archive'='geography-source-evidence'),
wanted(sha,size)AS(VALUES('c3085c5ff71bb04e68fdb84e26e62cfc2d9cc4aa773d2334e9387c5e83437524',974610),('6d8270fa50559adcfa0af2ab1637d76d0cb4ff98de1cbd5bdd003f6ea6993667',835682))
SELECT w.sha,w.size,net.http_get(url:='https://csebihpaychdkanjjsmz.supabase.co/storage/v1/object/authenticated/geography-source-evidence/'||w.sha||'.html',headers:=jsonb_build_object('apikey',secret.decrypted_secret,'Authorization','Bearer '||secret.decrypted_secret,'Accept-Encoding','identity','Range','bytes=0-1048575'),timeout_milliseconds:=20000) AS request_id
FROM wanted w JOIN storage.objects o ON o.bucket_id='geography-source-evidence' AND o.name=w.sha||'.html' AND (o.metadata->>'size')::integer=w.size JOIN storage.buckets b ON b.id=o.bucket_id AND NOT b.public CROSS JOIN secret CROSS JOIN j WHERE (SELECT count(*)FROM secret)=1; COMMIT;
